-- CASO 1 / Grupo 1. MySQL 8.4. Recreación de un esquema de demostración desde cero.
-- NOTA: MySQL initdb ejecuta este archivo solo en un volumen nuevo.
USE parques;
CREATE TABLE rol(idRol INT PRIMARY KEY, nombreRol VARCHAR(60) NOT NULL UNIQUE);
CREATE TABLE comunidad_autonoma(codigoComunidad INT PRIMARY KEY, nombre VARCHAR(100) NOT NULL, organismoResp VARCHAR(100), regionAdmin VARCHAR(100));
CREATE TABLE parque_natural(numCorrelativo INT PRIMARY KEY, nombre VARCHAR(130) NOT NULL, superficie DECIMAL(12,2) NOT NULL CHECK(superficie>0), fechaDeclaracion DATE, anioDeclaracion INT, estadoConservacion VARCHAR(40), presupuesto DECIMAL(14,2) NOT NULL DEFAULT 0 CHECK(presupuesto>=0), codigoComunidad INT NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(codigoComunidad) REFERENCES comunidad_autonoma(codigoComunidad));
CREATE TABLE trabajador(idTrabajador INT PRIMARY KEY, nombre VARCHAR(120) NOT NULL, direccion VARCHAR(150), fechaNacimiento DATE, estadoCuenta VARCHAR(25), idRol INT NOT NULL, idSupervisor INT NULL, numCorrelativo INT NOT NULL, FOREIGN KEY(idRol) REFERENCES rol(idRol), FOREIGN KEY(idSupervisor) REFERENCES trabajador(idTrabajador), FOREIGN KEY(numCorrelativo) REFERENCES parque_natural(numCorrelativo));
-- La asignación 1:1 de administrador es opcional y requiere comprobar rol; se registra por FK UNIQUE.
ALTER TABLE parque_natural ADD COLUMN idAdministrador INT NULL UNIQUE, ADD CONSTRAINT fk_parque_admin FOREIGN KEY(idAdministrador) REFERENCES trabajador(idTrabajador);
CREATE TABLE trabajador_funciones(idTrabajador INT NOT NULL, funcion VARCHAR(70) NOT NULL, PRIMARY KEY(idTrabajador,funcion), FOREIGN KEY(idTrabajador) REFERENCES trabajador(idTrabajador));
CREATE TABLE trabajador_contacto(idTrabajador INT NOT NULL, contacto VARCHAR(120) NOT NULL, PRIMARY KEY(idTrabajador,contacto), FOREIGN KEY(idTrabajador) REFERENCES trabajador(idTrabajador));
CREATE TABLE comparten(numCorrelativo INT NOT NULL,codigoComunidad INT NOT NULL,porcentajeTerritorial DECIMAL(5,2) NOT NULL CHECK(porcentajeTerritorial BETWEEN 0 AND 100),PRIMARY KEY(numCorrelativo,codigoComunidad),FOREIGN KEY(numCorrelativo) REFERENCES parque_natural(numCorrelativo),FOREIGN KEY(codigoComunidad) REFERENCES comunidad_autonoma(codigoComunidad));
CREATE TABLE area(numCorrelativo INT NOT NULL,numInterno INT NOT NULL,nombre VARCHAR(120) NOT NULL,estadoOperativo VARCHAR(30),nivelAcceso VARCHAR(30),extension DECIMAL(12,2) NOT NULL CHECK(extension>0),activo BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(numCorrelativo,numInterno), FOREIGN KEY(numCorrelativo) REFERENCES parque_natural(numCorrelativo));
CREATE TABLE proyecto_cientifico(idProyecto INT PRIMARY KEY,nombre VARCHAR(130) NOT NULL,objetivo VARCHAR(250),numCorrelativo INT NOT NULL,FOREIGN KEY(numCorrelativo) REFERENCES parque_natural(numCorrelativo));
CREATE TABLE participa(idTrabajador INT NOT NULL,idProyecto INT NOT NULL,PRIMARY KEY(idTrabajador,idProyecto),FOREIGN KEY(idTrabajador) REFERENCES trabajador(idTrabajador),FOREIGN KEY(idProyecto) REFERENCES proyecto_cientifico(idProyecto));
CREATE TABLE especie(idEspecie INT PRIMARY KEY,estadoConservacion VARCHAR(40),fechaIncorporacion DATE,nombreVulgar VARCHAR(120) NOT NULL,denominacionCientifica VARCHAR(150),tipo VARCHAR(20) NOT NULL DEFAULT 'Sin clasificar' CHECK(tipo IN ('Vegetal','Animal','Mineral','Sin clasificar')),activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE vegetal(idEspecie INT PRIMARY KEY,floracion VARCHAR(80),FOREIGN KEY(idEspecie) REFERENCES especie(idEspecie));
CREATE TABLE animal(idEspecie INT PRIMARY KEY,alimentacion VARCHAR(100),periodoCelo VARCHAR(80),FOREIGN KEY(idEspecie) REFERENCES especie(idEspecie));
CREATE TABLE mineral(idEspecie INT PRIMARY KEY,caracteristicasMineral VARCHAR(150),rocas VARCHAR(80),cristales VARCHAR(80),FOREIGN KEY(idEspecie) REFERENCES especie(idEspecie));
-- Las subtablas respetan FK pero exclusividad total entre subtipos requiere validación transaccional adicional.
CREATE TABLE investiga(idProyecto INT NOT NULL,idEspecie INT NOT NULL,PRIMARY KEY(idProyecto,idEspecie),FOREIGN KEY(idProyecto) REFERENCES proyecto_cientifico(idProyecto),FOREIGN KEY(idEspecie) REFERENCES especie(idEspecie));
CREATE TABLE se_desarrolla_en(idProyecto INT NOT NULL,numCorrelativo INT NOT NULL,numInterno INT NOT NULL,PRIMARY KEY(idProyecto,numCorrelativo,numInterno),FOREIGN KEY(idProyecto) REFERENCES proyecto_cientifico(idProyecto),FOREIGN KEY(numCorrelativo,numInterno) REFERENCES area(numCorrelativo,numInterno));
CREATE TABLE inventario_especie(codigoInventario INT PRIMARY KEY,cantidadInventario INT NOT NULL CHECK(cantidadInventario>=0),fechaUltimoMonitoreo DATE,observaciones VARCHAR(250),idEspecie INT NOT NULL,numCorrelativo INT NOT NULL,numInterno INT NOT NULL,FOREIGN KEY(idEspecie) REFERENCES especie(idEspecie),FOREIGN KEY(numCorrelativo,numInterno) REFERENCES area(numCorrelativo,numInterno));
CREATE TABLE excursion(numCorrelativo INT NOT NULL,numInterno INT NOT NULL,codigoExcursion INT NOT NULL,modalidad VARCHAR(60),horario TIME,fecha DATE NOT NULL,capacidad INT NOT NULL CHECK(capacidad>0),activo BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(numCorrelativo,numInterno,codigoExcursion),FOREIGN KEY(numCorrelativo,numInterno) REFERENCES area(numCorrelativo,numInterno));
CREATE TABLE visitante(idVisitante INT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,contacto VARCHAR(120),fechaNacimiento DATE);
CREATE TABLE inscripcion(idInscripcion INT PRIMARY KEY AUTO_INCREMENT,numCorrelativo INT NOT NULL,numInterno INT NOT NULL,codigoExcursion INT NOT NULL,idVisitante INT NOT NULL,asistencia BOOLEAN NOT NULL DEFAULT FALSE,observaciones VARCHAR(250),fechaRegistro DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(numCorrelativo,numInterno,codigoExcursion,idVisitante),FOREIGN KEY(numCorrelativo,numInterno,codigoExcursion) REFERENCES excursion(numCorrelativo,numInterno,codigoExcursion),FOREIGN KEY(idVisitante) REFERENCES visitante(idVisitante));
CREATE TABLE evaluacion(idInscripcion INT PRIMARY KEY,numCorrelativoEval INT UNIQUE,fecha DATE NOT NULL,calificacion DECIMAL(3,1) NOT NULL CHECK(calificacion BETWEEN 1 AND 7),comentario VARCHAR(250),FOREIGN KEY(idInscripcion) REFERENCES inscripcion(idInscripcion));
CREATE TABLE usuario(idUsuario INT PRIMARY KEY AUTO_INCREMENT,usuario VARCHAR(70) UNIQUE NOT NULL,claveHash VARCHAR(255) NOT NULL,rol VARCHAR(25) NOT NULL CHECK(rol IN ('administrador','consulta')),idTrabajador INT UNIQUE NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(idTrabajador) REFERENCES trabajador(idTrabajador));
CREATE INDEX idx_excursion_fecha ON excursion(fecha);
CREATE INDEX idx_inscripcion_excursion ON inscripcion(numCorrelativo,numInterno,codigoExcursion);
CREATE INDEX idx_inventario_area ON inventario_especie(numCorrelativo,numInterno);
